import { encodedLiteral, projectionFile } from "../rendering.js";
function pascalCase(value) {
    const titled = value.replace(/(^|[^A-Za-z0-9]+)([A-Za-z0-9])/g, (_match, _prefix, character) => character.toUpperCase());
    return titled.charAt(0).toUpperCase() + titled.slice(1);
}
function screamingSnakeCase(value) {
    return value.replace(/([a-z0-9])([A-Z])/g, "$1_$2").replace(/[^A-Za-z0-9]+/g, "_").toUpperCase();
}
function fileName(typeName) {
    return `${typeName.replace(/([a-z0-9])([A-Z])/g, "$1_$2").toLowerCase()}.generated.go`;
}
function render(definition) {
    const header = "// Code generated by tools/src/projection/providers/go/structural-projection-provider.ts; DO NOT EDIT.\n" +
        "package generated\n\n";
    if (definition.kind === "enum") {
        const names = definition.values.map((value) => `${definition.typeName}${pascalCase(String(value))}`);
        const width = Math.max(...names.map((name) => name.length));
        const constants = definition.values.map((value, index) => `\t${names[index].padEnd(width)} ${definition.typeName} = ${encodedLiteral("go", value)}`).join("\n");
        return header + `// ${definition.typeName} is a closed vocabulary projected from ${definition.sourcePointer}.\n` +
            `type ${definition.typeName} string\n\nconst (\n${constants}\n)\n`;
    }
    const constants = definition.constants.map((constant) => `const ${screamingSnakeCase(constant.name)} = ${encodedLiteral("go", constant.value)}\n`).join("");
    const renderedFields = definition.fields.map((field) => {
        const jsonName = field.name.endsWith("_") ? field.name.slice(0, -1) : field.name;
        return { name: pascalCase(jsonName), type: field.type, jsonName };
    });
    const nameWidth = Math.max(...renderedFields.map((field) => field.name.length));
    const typeWidth = Math.max(...renderedFields.map((field) => field.type.length));
    const fields = renderedFields.map((field) => `\t${field.name.padEnd(nameWidth)} ${field.type.padEnd(typeWidth)} \`json:"${field.jsonName},omitempty"\``).join("\n");
    return header + constants + (constants ? "\n" : "") +
        `// ${definition.typeName} is projected from kernel/schemas/${definition.sourcePointer.replace(/#$/, "")}.\n` +
        `type ${definition.typeName} struct {\n${fields}\n}\n`;
}
export class GoStructuralProjectionProvider {
    target = "go";
    render(graph, profile) {
        if (graph.target !== this.target || profile.language !== this.target)
            throw new Error("Go renderer received another target.");
        return {
            planType: "projection-plan.v1",
            target: this.target,
            outputDirectory: profile.outputDirectory,
            files: graph.definitions.map((definition) => projectionFile(fileName(definition.typeName), render(definition), definition))
        };
    }
}
